`,(0,n.jsx)(o,{children:(0,n.jsx)(r.p,{children:"Based on the workflow improvement I've defined, create the specific materials I need to implement this: example prompts I'll use, any template files I should have, specific MCP connections to set up, and a step-by-step guide I can follow."})}),`
